@layer components {
  :where([data-control-family="avatar"][data-slot="root"]) {
    --cui-avatar-image-outline-color: var(--image-outline);
    --cui-avatar-badge-size: max(0.5rem, 30%);
    --cui-avatar-badge-ring-size: 2px;
    --cui-avatar-badge-ring-color: var(--background);
    --cui-avatar-badge-background: var(--primary);
    --cui-avatar-badge-foreground: var(--primary-foreground);
    inline-size: calc(var(--spacing) * 9);
    block-size: calc(var(--spacing) * 9);
  }

  :where([data-control-family="avatar"][data-slot="root"]),
  :where([data-control-family="avatar"][data-slot="favicon"]),
  :where([data-control-family="avatar"][data-slot="source-favicon"]) {
    --cui-avatar-radius: 9999px;
    --cui-avatar-group-ring-color: var(--background);
    --cui-avatar-fallback-background: var(--muted);
    --cui-avatar-fallback-foreground: var(--muted-foreground);
    border-radius: var(--cui-avatar-radius);
  }

  :where([data-control-family="avatar"][data-slot="root"])::after {
    content: "";
    position: absolute;
    inset: 0;
    pointer-events: none;
    border-radius: inherit;
    box-shadow: inset 0 0 0 1px var(--cui-avatar-image-outline-color);
  }

  :where([data-control-family="avatar"][data-slot="group"] > [data-control-family="avatar"]) {
    box-shadow: 0 0 0 2px var(--cui-avatar-group-ring-color);
  }

  :where([data-control-family="avatar"][data-slot="image"]) {
    border-radius: inherit;
  }

  :where([data-control-family="avatar"][data-slot="badge"]) {
    z-index: 1;
    inset-block-end: 0;
    inset-inline-end: 0;
    inline-size: var(--cui-avatar-badge-size);
    aspect-ratio: 1;
    border-radius: 9999px;
    background: var(--cui-avatar-badge-background);
    color: var(--cui-avatar-badge-foreground);
    box-shadow: 0 0 0 var(--cui-avatar-badge-ring-size) var(--cui-avatar-badge-ring-color);
    font-size: 0.5rem;
    font-weight: var(--font-weight-medium);
    font-variant-numeric: tabular-nums;
    line-height: 1;
    transition: background-color var(--duration-fast) var(--ease-standard);
  }

  :where([data-control-family="avatar"][data-slot="badge"] > svg) {
    inline-size: 70%;
    block-size: 70%;
  }

  :where([data-control-family="avatar"][data-slot="badge"][data-status="online"]) {
    --cui-avatar-badge-background: var(--success-text);
  }

  :where([data-control-family="avatar"][data-slot="badge"][data-status="away"]) {
    --cui-avatar-badge-background: var(--warning-text);
  }

  :where([data-control-family="avatar"][data-slot="badge"][data-status="busy"]) {
    --cui-avatar-badge-background: var(--destructive);
  }

  :where([data-control-family="avatar"][data-slot="badge"][data-status="offline"]) {
    --cui-avatar-badge-background: oklch(from var(--muted-foreground) l c h / 0.6);
  }

  :where([data-control-family="avatar"][data-slot="fallback"]) {
    border-radius: inherit;
    background: var(--cui-avatar-fallback-background);
    color: var(--cui-avatar-fallback-foreground);
    font-size: var(--text-caption);
    font-weight: var(--font-weight-medium);
  }
}

@property --cui-avatar-radius {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-avatar-group-ring-color {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-avatar-fallback-background {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-avatar-fallback-foreground {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-avatar-image-outline-color {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-avatar-badge-size {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-avatar-badge-ring-size {
  syntax: "<length>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-avatar-badge-ring-color {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-avatar-badge-background {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-avatar-badge-foreground {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

"use client";

import { Avatar as AvatarPrimitive } from "@base-ui/react/avatar";
import type { ComponentProps, CSSProperties } from "react";
import type { AvatarKnobStyle } from "@/components/control-ui/knob-contracts/avatar-knobs";
import { cn } from "@/components/control-ui/lib/cn";

export type AvatarProps = Omit<ComponentProps<"span">, "style"> & { style?: CSSProperties & AvatarKnobStyle };

export type AvatarGroupProps = Omit<ComponentProps<"div">, "style"> & { style?: CSSProperties & AvatarKnobStyle };

export type AvatarImageProps = ComponentProps<"img"> & {
  onLoadingStatusChange?: (status: "idle" | "loading" | "loaded" | "error") => void;
} & { style?: CSSProperties & AvatarKnobStyle };

export type AvatarFallbackProps = Omit<ComponentProps<"span">, "style"> & {
  delay?: number;
  style?: CSSProperties & AvatarKnobStyle;
};

export const avatarBadgeStatuses = ["online", "away", "busy", "offline"] as const;

export type AvatarBadgeStatus = (typeof avatarBadgeStatuses)[number];

export type AvatarBadgeProps = Omit<ComponentProps<"span">, "style"> & {
  status?: AvatarBadgeStatus;
  label?: string;
  style?: CSSProperties & AvatarKnobStyle;
};

export function Avatar({ className, ...props }: AvatarProps) {
  return (
    <AvatarPrimitive.Root
      data-control-ui="avatar"
      data-control-family="avatar"
      data-slot="root"
      className={cn("relative inline-flex shrink-0 select-none items-center justify-center align-middle", className)}
      {...props}
    />
  );
}

export function AvatarGroup({ className, ...props }: AvatarGroupProps) {
  return (
    // biome-ignore lint/a11y/useSemanticElements: Profile imagery is not a form fieldset.
    <div
      role="group"
      data-control-ui="avatar"
      data-control-family="avatar"
      data-slot="group"
      className={cn("isolate inline-flex items-center -space-x-2", className)}
      {...props}
    />
  );
}

export function AvatarImage({ className, ...props }: AvatarImageProps) {
  return (
    <AvatarPrimitive.Image
      data-control-ui="avatar"
      data-control-family="avatar"
      data-slot="image"
      className={cn("size-full object-cover", className)}
      {...props}
    />
  );
}

export function AvatarFallback({ className, ...props }: AvatarFallbackProps) {
  return (
    <AvatarPrimitive.Fallback
      data-control-ui="avatar"
      data-control-family="avatar"
      data-slot="fallback"
      className={cn("flex size-full items-center justify-center", className)}
      {...props}
    />
  );
}

export function AvatarBadge({ className, status, label, children, ...props }: AvatarBadgeProps) {
  return (
    <span
      data-control-ui="avatar"
      data-control-family="avatar"
      data-slot="badge"
      data-status={status}
      className={cn("absolute inline-flex items-center justify-center", className)}
      {...props}
    >
      {children}
      {label ? <span className="sr-only">{label}</span> : null}
    </span>
  );
}
